def solve(rows):
    if not rows:
        return []

    # Audit filter
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 5 != 1 or i == len(rows) - 1:
            filtered_rows.append(row)

    # Rotate
    if filtered_rows:
        filtered_rows = filtered_rows[2:] + filtered_rows[:2]

    # Sort and deduplicate
    filtered_rows = sorted(list(set(filtered_rows)))

    # Create sessions
    sessions = []
    if filtered_rows:
        start = filtered_rows[0]
        end = filtered_rows[0]
        count = 1

        for i in range(1, len(filtered_rows)):
            if filtered_rows[i] - end > 5:
                sessions.append([start, end, count])
                start = filtered_rows[i]
                end = filtered_rows[i]
                count = 1
            else:
                end = filtered_rows[i]
                count += 1

        sessions.append([start, end, count])

    return sessions

